select.where:
del_flag='0'
 and month_plan_aps_version = #{monthPlanApsVersion}
 and material_code = #{materialCode}
 and spec_desc = #{specDesc}
 and embryo_code = #{embryoCode}
 and quality_grade = #{qualityGrade}
 and storage_location = #{storageLocation}
 and special_requirements = #{specialRequirements}
 and expected_excess_arrears = #{expectedExcessArrears}
 and theory_production_plan = #{theoryProductionPlan}
 and actual_arrangement = #{actualArrangement}
 and balance = #{balance}
 and lh_machine_code = #{lhMachineCode}
 and lh_machine_name like concat(concat('%', #{lhMachineName}), '%')
 and cx_machine_code = #{cxMachineCode}
 and cx_machine_name like concat(concat('%', #{cxMachineName}), '%')

mapper.select:
SELECT t.*, nvl( csls.product_sort, 0 ) product_sort FROM ( SELECT mmpp.material_code, mmpp.embryo_code, mmpp.bom_data_version, mmpp.storage_location, sum( nvl( mmpp.actual_arrangement, 0 )) month_total_plan_qty FROM t_mdm_month_prod_plan mmpp
mmpp.del_flag = '0' AND mmpp.month_plan_aps_version = #{ monthPlanApsVersion }
GROUP BY material_code, embryo_code, bom_data_version, storage_location having sum( nvl( mmpp.actual_arrangement, 0 ))>0 ) t LEFT JOIN T_CX_STOCK_LOCATION_SORT CSLS ON t.storage_location = csls.STOCK_LOCATION AND csls.del_flag = '0' ORDER BY t.material_code ASC, csls.product_sort ASC

