em.finishQty19,jdbcType=NUMERIC}, #{item.productQty20,jdbcType=NUMERIC},#{item.finishQty20,jdbcType=NUMERIC},#{item.productQty21,jdbcType=NUMERIC}, #{item.finishQty21,jdbcType=NUMERIC},#{item.productQty22,jdbcType=NUMERIC},#{item.finishQty22,jdbcType=NUMERIC}, #{item.productQty23,jdbcType=NUMERIC},#{item.finishQty23,jdbcType=NUMERIC},#{item.productQty24,jdbcType=NUMERIC}, #{item.finishQty24,jdbcType=NUMERIC},#{item.productQty25,jdbcType=NUMERIC},#{item.finishQty25,jdbcType=NUMERIC}, #{item.productQty26,jdbcType=NUMERIC},#{item.finishQty26,jdbcType=NUMERIC},#{item.productQty27,jdbcType=NUMERIC}, #{item.finishQty27,jdbcType=NUMERIC},#{item.productQty28,jdbcType=NUMERIC},#{item.finishQty28,jdbcType=NUMERIC}, #{item.productQty29,jdbcType=NUMERIC},#{item.finishQty29,jdbcType=NUMERIC},#{item.productQty30,jdbcType=NUMERIC}, #{item.finishQty30,jdbcType=NUMERIC},#{item.productQty31,jdbcType=NUMERIC},#{item.finishQty31,jdbcType=NUMERIC}, #{item.createBy,jdbcType=VARCHAR},#{item.createTime,jdbcType=TIMESTAMP},#{item.updateBy,jdbcType=VARCHAR}, #{item.updateTime,jdbcType=TIMESTAMP},#{item.delFlag,jdbcType=VARCHAR},#{item.remark,jdbcType=VARCHAR}, #{item.specDimension,jdbcType=DECIMAL},#{item.storageLocationDesc,jdbcType=VARCHAR},#{item.actualOverProduction,jdbcType=NUMERIC}, #{item.planModifyQty,jdbcType=NUMERIC},#{item.beginDate,jdbcType=TIMESTAMP},#{item.endDate,jdbcType=TIMESTAMP}, #{item.dataSource,jdbcType=VARCHAR},#{item.bomDataVersion,jdbcType=VARCHAR} from dual
