mapper.select:
SELECT mmpp.material_code, mmpp.embryo_code, mmpp.bom_data_version, sum( nvl( mmpp.actual_arrangement, 0 )) month_total_plan_qty FROM t_mdm_month_plan_main mmpm LEFT JOIN t_mdm_month_prod_plan mmpp ON mmpm.MONTH_PLAN_APS_VERSION= mmpp.MONTH_PLAN_APS_VERSION
mmpm.del_flag='0' and mmpp.del_flag = '0'
AND mmpm.year = #{ year }
AND mmpm.month = #{ month }
AND mmpm.IS_FINALIZED = #{ isFinalized }
AND mmpm.MONTH_PLAN_APS_VERSION = #{ monthPlanApsVersion }
GROUP BY material_code, embryo_code, bom_data_version
